package com.bank.credittrend.service;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.logging.Logger;

// Quadratic LIS tabulation with predecessor links to rebuild the sequence.
public class CreditTrendService {
    private static final Logger log = Logger.getLogger(CreditTrendService.class.getName());

    public List<Integer> longestRisingSequence(int[] balances) {
        int n = balances.length;
        if (n == 0) return List.of();
        int[] len = new int[n];                            // len[i] = LIS length ending at i
        int[] prev = new int[n];                           // predecessor index for reconstruction
        int bestLen = 1, bestEnd = 0;
        for (int i = 0; i < n; i++) {
            len[i] = 1;
            prev[i] = -1;
            for (int j = 0; j < i; j++) {
                if (balances[j] < balances[i] && len[j] + 1 > len[i]) {
                    len[i] = len[j] + 1;                   // extend the best smaller-earlier run
                    prev[i] = j;                           // remember where we came from
                }
            }
            if (len[i] > bestLen) { bestLen = len[i]; bestEnd = i; }
        }
        List<Integer> run = new ArrayList<>();
        for (int at = bestEnd; at != -1; at = prev[at]) run.add(balances[at]);
        Collections.reverse(run);                          // links go backward; flip to forward
        log.info(() -> "Longest rising run of balances = " + run);
        return run;
    }
}
