package com.bank.credittrend;

import com.bank.credittrend.service.CreditTrendService;
import java.util.List;
import java.util.logging.Logger;

public class CreditTrendApplication {
    private static final Logger log = Logger.getLogger(CreditTrendApplication.class.getName());

    public static void main(String[] args) {
        CreditTrendService service = new CreditTrendService();
        int[] balances = {3, 4, 1, 5};                     // monthly closing balances (scaled)
        List<Integer> run = service.longestRisingSequence(balances);
        log.info(() -> "Final reconstructed run = " + run);
    }
}
